ALTER TABLE public.project_boq ADD COLUMN IF NOT EXISTS entry_mode text NOT NULL DEFAULT 'legacy', ADD COLUMN IF NOT EXISTS control_total numeric, ADD COLUMN IF NOT EXISTS status text NOT NULL DEFAULT 'draft', ADD COLUMN IF NOT EXISTS source_note text, ADD COLUMN IF NOT EXISTS final_at timestamptz, ADD COLUMN IF NOT EXISTS final_by uuid, ADD COLUMN IF NOT EXISTS created_by uuid, ADD COLUMN IF NOT EXISTS updated_by uuid, ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS entry_version integer NOT NULL DEFAULT 0;
ALTER TABLE public.project_boq ADD CONSTRAINT boq1_header_status CHECK (status IN ('draft','final')), ADD CONSTRAINT boq1_entry_mode CHECK (entry_mode IN ('legacy','fresh'));
CREATE UNIQUE INDEX boq1_one_fresh_active ON public.project_boq(project_id) WHERE entry_mode='fresh' AND NOT is_archived;
ALTER TABLE public.project_boq_items ADD COLUMN IF NOT EXISTS is_archived boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS created_by uuid, ADD COLUMN IF NOT EXISTS updated_by uuid, ADD COLUMN IF NOT EXISTS updated_at timestamptz NOT NULL DEFAULT now(), ADD COLUMN IF NOT EXISTS entry_managed boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS quantity_missing boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS rate_missing boolean NOT NULL DEFAULT false;
CREATE UNIQUE INDEX boq1_unique_item_number ON public.project_boq_items(boq_id,sno) WHERE entry_managed AND NOT is_archived;
CREATE OR REPLACE FUNCTION public.boq1_can_read(p_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT auth.uid() IS NOT NULL AND public.user_can_access_project(auth.uid(),p_project) AND public.user_has_any_role(auth.uid(),ARRAY['super_admin','managing_director','chairman','finance_director','finance_manager','accounts_executive','planning_head','planning_engineer','costing_engineer','quantity_surveyor','architecture_director','principal_architect','project_architect','head_operations','head_of_projects','sales_director']::public.app_role[]); $$;
CREATE OR REPLACE FUNCTION public.boq1_can_write(p_project uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ SELECT public.boq1_can_read(p_project) AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=auth.uid() AND is_active AND NOT is_archived) AND public.user_has_any_role(auth.uid(),ARRAY['super_admin','managing_director','finance_director','finance_manager','planning_engineer','architecture_director','project_architect','principal_architect','sales_director','planning_head']::public.app_role[]); $$;
CREATE TABLE public.boq_entry_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.projects(id), boq_id uuid NOT NULL REFERENCES public.project_boq(id), line_id uuid, action text NOT NULL, reason text, old_value jsonb, new_value jsonb, created_by uuid NOT NULL, updated_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_archived boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.boq_entry_audit TO authenticated; GRANT ALL ON public.boq_entry_audit TO service_role;
ALTER TABLE public.boq_entry_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY boq1_read_audit ON public.boq_entry_audit FOR SELECT TO authenticated USING(public.boq1_can_read(project_id));
CREATE TABLE public.boq_warning_acknowledgements(id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES public.projects(id), boq_id uuid NOT NULL REFERENCES public.project_boq(id), line_id uuid NOT NULL REFERENCES public.project_boq_items(id), warning_key text NOT NULL, warning jsonb NOT NULL, note text, created_by uuid NOT NULL, updated_by uuid NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), is_archived boolean NOT NULL DEFAULT false, UNIQUE(boq_id,line_id,warning_key));
GRANT SELECT ON public.boq_warning_acknowledgements TO authenticated; GRANT ALL ON public.boq_warning_acknowledgements TO service_role;
ALTER TABLE public.boq_warning_acknowledgements ENABLE ROW LEVEL SECURITY;
CREATE POLICY boq1_read_ack ON public.boq_warning_acknowledgements FOR SELECT TO authenticated USING(public.boq1_can_read(project_id));
CREATE OR REPLACE FUNCTION public._boq1_number(p_value text,p_label text,p_paise boolean DEFAULT false) RETURNS numeric LANGUAGE plpgsql IMMUTABLE SET search_path=public,pg_temp AS $$ DECLARE v numeric; BEGIN IF p_value IS NULL OR btrim(p_value)='' THEN RETURN 0; END IF; IF length(p_value)>60 OR p_value !~ '^[0-9]+(\.[0-9]+)?$' THEN RAISE EXCEPTION '% must be a finite non-negative number',p_label USING ERRCODE='22023'; END IF; v:=p_value::numeric; IF v>1000000000000000000 THEN RAISE EXCEPTION '% is too large',p_label USING ERRCODE='22023'; END IF; IF p_paise AND v<>round(v,2) THEN RAISE EXCEPTION '% must have at most two decimal places',p_label USING ERRCODE='22023'; END IF; RETURN v; END $$;
CREATE OR REPLACE FUNCTION public._boq1_normal(p_text text) RETURNS text LANGUAGE sql IMMUTABLE SET search_path=public,pg_temp AS $$ SELECT lower(regexp_replace(btrim(coalesce(p_text,'')),'\s+',' ','g')); $$;
CREATE OR REPLACE FUNCTION public._boq1_warnings(p_boq uuid,p_row jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE result jsonb:='[]'; m numeric; n integer; w jsonb; q numeric; r numeric; project uuid; BEGIN SELECT project_id INTO project FROM public.project_boq WHERE id=p_boq; q:=coalesce((p_row->>'boq_qty')::numeric,0); r:=coalesce((p_row->>'boq_rate')::numeric,0); IF EXISTS(SELECT 1 FROM public.project_boq_items i WHERE i.boq_id=p_boq AND NOT i.is_archived AND i.id::text IS DISTINCT FROM p_row->>'id' AND public._boq1_normal(i.item_description)=public._boq1_normal(p_row->>'item_description') AND public._boq1_normal(i.unit)=public._boq1_normal(p_row->>'unit')) THEN result:=result||jsonb_build_array(jsonb_build_object('kind','duplicate','message','Same description and unit appear on another line.')); END IF;
IF q=0 OR coalesce((p_row->>'quantity_missing')::boolean,false) THEN result:=result||jsonb_build_array(jsonb_build_object('kind','quantity','message','Quantity is zero or missing.')); END IF;
IF r=0 OR coalesce((p_row->>'rate_missing')::boolean,false) THEN result:=result||jsonb_build_array(jsonb_build_object('kind','rate','message','Rate is zero or missing.')); END IF;
IF scale(r)>2 THEN result:=result||jsonb_build_array(jsonb_build_object('kind','precision','message','Rate has more than two decimal places; the line amount is rounded to paise.')); END IF;
WITH latest AS (SELECT DISTINCT ON(h.project_id) h.id,h.project_id FROM public.project_boq h JOIN public.projects p ON p.id=h.project_id WHERE h.project_id<>project AND NOT h.is_archived AND NOT p.is_archived ORDER BY h.project_id,h.version_number DESC,h.uploaded_at DESC,h.id DESC), per_project AS (SELECT h.project_id,percentile_cont(0.5) WITHIN GROUP(ORDER BY i.boq_rate)::numeric rate FROM latest h JOIN public.project_boq_items i ON i.boq_id=h.id WHERE NOT i.is_archived AND i.boq_rate::text NOT IN ('NaN','Infinity','-Infinity') AND i.boq_rate>=0 AND public._boq1_normal(i.item_description)=public._boq1_normal(p_row->>'item_description') AND public._boq1_normal(i.unit)=public._boq1_normal(p_row->>'unit') GROUP BY h.project_id) SELECT count(*),percentile_cont(0.5) WITHIN GROUP(ORDER BY rate)::numeric INTO n,m FROM per_project;
IF n>=3 AND (r<m*0.75 OR r>m*1.25) THEN result:=result||jsonb_build_array(jsonb_build_object('kind','outlier','message','Rate differs by more than 25% from the median across other projects.','median_rate',m,'project_count',n)); END IF;
RETURN coalesce((SELECT jsonb_agg(value||jsonb_build_object('key',md5(value::text||coalesce(p_row->>'item_description','')||coalesce(p_row->>'unit','')||q::text||r::text))) FROM jsonb_array_elements(result)),'[]'); END $$;
CREATE OR REPLACE FUNCTION public._boq1_header_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ BEGIN
IF TG_OP='DELETE' THEN IF OLD.entry_mode='fresh' THEN RAISE EXCEPTION 'BOQs are archived, never permanently deleted' USING ERRCODE='42501'; END IF; RETURN OLD; END IF;
IF NEW.entry_mode='fresh' OR (TG_OP='UPDATE' AND OLD.entry_mode='fresh') THEN
IF current_user NOT IN ('postgres','supabase_admin') OR current_setting('hstack.boq_entry',true) IS DISTINCT FROM NEW.id::text THEN RAISE EXCEPTION 'Use the checked BOQ entry or revision action; direct changes are not allowed' USING ERRCODE='42501'; END IF;
IF TG_OP='UPDATE' AND OLD.entry_mode='legacy' THEN RAISE EXCEPTION 'Existing BOQs remain unchanged' USING ERRCODE='42501'; END IF;
IF NEW.control_total IS NULL OR NEW.control_total::text IN ('NaN','Infinity','-Infinity') OR NEW.control_total<0 OR NEW.control_total<>round(NEW.control_total,2) OR nullif(btrim(NEW.source_note),'') IS NULL THEN RAISE EXCEPTION 'A non-negative control total in paise and source note are required' USING ERRCODE='22023'; END IF;
IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.uploaded_by:=auth.uid(); NEW.uploaded_at:=now(); NEW.created_at:=now(); END IF;
NEW.updated_by:=auth.uid(); NEW.updated_at:=now();
ELSIF TG_OP='INSERT' AND EXISTS(SELECT 1 FROM public.project_boq WHERE project_id=NEW.project_id AND entry_mode='fresh' AND NOT is_archived) THEN RAISE EXCEPTION 'This project uses fresh BOQ entry; another upload cannot replace it' USING ERRCODE='42501'; END IF; RETURN NEW; END $$;
CREATE TRIGGER aaa_boq1_header_guard BEFORE INSERT OR UPDATE OR DELETE ON public.project_boq FOR EACH ROW EXECUTE FUNCTION public._boq1_header_guard();
CREATE OR REPLACE FUNCTION public._boq1_line_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public,pg_temp AS $$ DECLARE h public.project_boq%ROWTYPE; BEGIN SELECT * INTO h FROM public.project_boq WHERE id=CASE WHEN TG_OP='DELETE' THEN OLD.boq_id ELSE NEW.boq_id END;
IF h.entry_mode<>'fresh' THEN IF TG_OP='UPDATE' AND OLD.entry_managed THEN RAISE EXCEPTION 'A fresh BOQ line cannot be moved to another BOQ' USING ERRCODE='42501'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END IF;
IF TG_OP='DELETE' THEN RAISE EXCEPTION 'BOQ lines are archived, never permanently deleted' USING ERRCODE='42501'; END IF;
IF current_user NOT IN ('postgres','supabase_admin') OR current_setting('hstack.boq_entry',true) IS DISTINCT FROM h.id::text THEN RAISE EXCEPTION 'Final BOQ lines are locked; use BOQ entry or a reasoned revision' USING ERRCODE='42501'; END IF;
IF TG_OP='UPDATE' AND (NEW.boq_id IS DISTINCT FROM OLD.boq_id OR NOT OLD.entry_managed) THEN RAISE EXCEPTION 'Existing BOQ lines cannot be replaced or moved' USING ERRCODE='42501'; END IF;
IF NEW.sno<=0 OR nullif(btrim(NEW.item_description),'') IS NULL OR nullif(btrim(NEW.unit),'') IS NULL OR NEW.boq_qty::text IN ('NaN','Infinity','-Infinity') OR NEW.boq_rate::text IN ('NaN','Infinity','-Infinity') OR NEW.boq_qty<0 OR NEW.boq_rate<0 THEN RAISE EXCEPTION 'Item number, description, unit and finite non-negative quantity/rate are required' USING ERRCODE='22023'; END IF;
NEW.entry_managed:=true; NEW.total_amount:=round(NEW.boq_qty*NEW.boq_rate,2); NEW.tender_qty:=NEW.boq_qty; NEW.tender_amount:=NEW.total_amount;
IF TG_OP='INSERT' THEN NEW.created_by:=auth.uid(); NEW.created_at:=now(); END IF; NEW.updated_by:=auth.uid(); NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER aaa_boq1_line_guard BEFORE INSERT OR UPDATE OR DELETE ON public.project_boq_items FOR EACH ROW EXECUTE FUNCTION public._boq1_line_guard();
CREATE OR REPLACE FUNCTION public._boq1_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE h public.project_boq%ROWTYPE; BEGIN IF TG_TABLE_NAME='project_boq' THEN h:=NEW; ELSE SELECT * INTO h FROM public.project_boq WHERE id=NEW.boq_id; END IF; IF h.entry_mode='fresh' THEN INSERT INTO public.boq_entry_audit(project_id,boq_id,line_id,action,reason,old_value,new_value,created_by,updated_by) VALUES(h.project_id,h.id,CASE WHEN TG_TABLE_NAME='project_boq_items' THEN NEW.id ELSE NULL END,coalesce(nullif(current_setting('hstack.boq_action',true),''),lower(TG_OP)),nullif(current_setting('hstack.boq_reason',true),''),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) ELSE NULL END,to_jsonb(NEW),auth.uid(),auth.uid()); END IF; RETURN NEW; END $$;
CREATE TRIGGER boq1_header_audit AFTER INSERT OR UPDATE ON public.project_boq FOR EACH ROW EXECUTE FUNCTION public._boq1_audit();
CREATE TRIGGER boq1_line_audit AFTER INSERT OR UPDATE ON public.project_boq_items FOR EACH ROW EXECUTE FUNCTION public._boq1_audit();
CREATE OR REPLACE FUNCTION public._boq1_rows(p_boq uuid,p_rows jsonb,p_apply boolean) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE row jsonb; clean jsonb; result jsonb:='[]'; errors jsonb; warnings jsonb; v_id uuid; v_sno integer; v_qty numeric; v_rate numeric; ordinal integer:=0; BEGIN
IF jsonb_typeof(p_rows)<>'array' OR jsonb_array_length(p_rows)>500 THEN RAISE EXCEPTION 'Paste up to 500 rows at a time' USING ERRCODE='22023'; END IF;
FOR row IN SELECT value FROM jsonb_array_elements(p_rows) LOOP ordinal:=ordinal+1; errors:='[]'; clean:=NULL; v_id:=NULL;
BEGIN
IF jsonb_typeof(row)<>'object' OR (row - ARRAY['id','sno','item_description','unit','boq_qty','boq_rate','category','scope','work_location','remove'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Only entry fields may be supplied; actor, timestamps and amounts are server-filled' USING ERRCODE='22023'; END IF;
IF nullif(row->>'id','') IS NOT NULL THEN v_id:=(row->>'id')::uuid; IF NOT EXISTS(SELECT 1 FROM public.project_boq_items WHERE id=v_id AND boq_id=p_boq AND entry_managed AND NOT is_archived) THEN RAISE EXCEPTION 'Line is not in this active BOQ' USING ERRCODE='42501'; END IF; END IF;
IF coalesce((row->>'remove')::boolean,false) THEN
IF v_id IS NULL THEN RAISE EXCEPTION 'Choose a saved line to remove'; END IF;
IF p_apply THEN UPDATE public.project_boq_items SET is_archived=true,boq_qty=0,boq_rate=0 WHERE id=v_id; END IF;
result:=result||jsonb_build_array(jsonb_build_object('row',ordinal,'id',v_id,'errors',errors,'warnings','[]'::jsonb)); CONTINUE; END IF;
IF coalesce(row->>'sno','') !~ '^[0-9]+$' OR length(row->>'sno')>9 THEN RAISE EXCEPTION 'Item number must be a positive whole number'; END IF; v_sno:=(row->>'sno')::integer; IF v_sno<=0 THEN RAISE EXCEPTION 'Item number must be positive'; END IF;
IF nullif(btrim(row->>'item_description'),'') IS NULL THEN RAISE EXCEPTION 'Description is required'; END IF; IF nullif(btrim(row->>'unit'),'') IS NULL THEN RAISE EXCEPTION 'Unit is required'; END IF;
IF coalesce(row->>'scope','') NOT IN ('Factory','On-Site Civil','Both','Habitainer') THEN RAISE EXCEPTION 'Select an existing scope'; END IF; IF coalesce(row->>'work_location','') NOT IN ('site','factory') THEN RAISE EXCEPTION 'Select site or factory work location'; END IF;
IF EXISTS(SELECT 1 FROM public.project_boq_items WHERE boq_id=p_boq AND NOT is_archived AND sno=v_sno AND id IS DISTINCT FROM v_id) OR (SELECT count(*) FROM jsonb_array_elements(p_rows) e WHERE e->>'sno'=row->>'sno' AND NOT coalesce((e->>'remove')::boolean,false))>1 THEN RAISE EXCEPTION 'Item number % is repeated; each item number must be unique',v_sno; END IF;
v_qty:=public._boq1_number(row->>'boq_qty','Quantity'); v_rate:=public._boq1_number(row->>'boq_rate','Rate');
clean:=jsonb_build_object('id',v_id,'sno',v_sno,'item_description',btrim(row->>'item_description'),'unit',btrim(row->>'unit'),'boq_qty',v_qty,'boq_rate',v_rate,'category',coalesce(row->>'category',''),'scope',row->>'scope','work_location',row->>'work_location','quantity_missing',nullif(btrim(row->>'boq_qty'),'') IS NULL,'rate_missing',nullif(btrim(row->>'boq_rate'),'') IS NULL,'total_amount',round(v_qty*v_rate,2));
warnings:=public._boq1_warnings(p_boq,clean);
IF EXISTS(SELECT 1 FROM jsonb_array_elements(p_rows) e WHERE e IS DISTINCT FROM row AND public._boq1_normal(e->>'item_description')=public._boq1_normal(row->>'item_description') AND public._boq1_normal(e->>'unit')=public._boq1_normal(row->>'unit')) AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(warnings) w WHERE w->>'kind'='duplicate') THEN warnings:=warnings||jsonb_build_array(jsonb_build_object('kind','duplicate','message','Same description and unit appear in this paste batch.')); END IF;
IF p_apply THEN
IF v_id IS NULL THEN INSERT INTO public.project_boq_items(boq_id,sno,item_description,unit,boq_qty,boq_rate,category,scope,work_location,quantity_missing,rate_missing) VALUES(p_boq,v_sno,clean->>'item_description',clean->>'unit',v_qty,v_rate,clean->>'category',clean->>'scope',clean->>'work_location',(clean->>'quantity_missing')::boolean,(clean->>'rate_missing')::boolean) RETURNING id INTO v_id;
ELSE UPDATE public.project_boq_items SET sno=v_sno,item_description=clean->>'item_description',unit=clean->>'unit',boq_qty=v_qty,boq_rate=v_rate,category=clean->>'category',scope=clean->>'scope',work_location=clean->>'work_location',quantity_missing=(clean->>'quantity_missing')::boolean,rate_missing=(clean->>'rate_missing')::boolean WHERE id=v_id; END IF; END IF;
EXCEPTION WHEN OTHERS THEN errors:=jsonb_build_array(SQLERRM); warnings:='[]'; END;
result:=result||jsonb_build_array(jsonb_build_object('row',ordinal,'id',v_id,'values',clean,'errors',errors,'warnings',coalesce(warnings,'[]')));
END LOOP; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.boq1_get(p_project uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE h public.project_boq%ROWTYPE; lines jsonb; total numeric; count integer; BEGIN IF NOT public.boq1_can_read(p_project) THEN RAISE EXCEPTION 'You do not have access to this project BOQ' USING ERRCODE='42501'; END IF;
SELECT * INTO h FROM public.project_boq WHERE project_id=p_project AND NOT is_archived ORDER BY version_number DESC,uploaded_at DESC,id DESC LIMIT 1;
SELECT coalesce(sum(total_amount),0),count(*) INTO total,count FROM public.project_boq_items WHERE boq_id=h.id AND NOT is_archived;
SELECT coalesce(jsonb_agg(to_jsonb(i)||jsonb_build_object('warnings',CASE WHEN h.entry_mode='fresh' THEN (SELECT coalesce(jsonb_agg(w||jsonb_build_object('acknowledged',EXISTS(SELECT 1 FROM public.boq_warning_acknowledgements a WHERE a.boq_id=h.id AND a.line_id=i.id AND a.warning_key=w->>'key' AND NOT a.is_archived))),'[]') FROM jsonb_array_elements(public._boq1_warnings(h.id,to_jsonb(i))) w) ELSE '[]'::jsonb END) ORDER BY i.sno),'[]') INTO lines FROM public.project_boq_items i WHERE i.boq_id=h.id AND NOT i.is_archived;
RETURN jsonb_build_object('header',CASE WHEN h.id IS NULL THEN NULL ELSE to_jsonb(h) END,'lines',lines,'sum',total,'difference',CASE WHEN h.control_total IS NOT NULL THEN h.control_total-total ELSE NULL END,'line_count',count,'can_write',public.boq1_can_write(p_project),'can_finalise',h.entry_mode='fresh' AND h.status='draft' AND count>0 AND h.control_total=total,'units',(SELECT coalesce(jsonb_agg(unit ORDER BY unit),'[]') FROM (SELECT DISTINCT unit FROM public.project_boq_items WHERE nullif(btrim(unit),'') IS NOT NULL UNION SELECT unnest(ARRAY['units','kg','tonnes','litres','sqm','sqft','metres','nos','bags','sheets','rolls'])) u),'categories',(SELECT coalesce(jsonb_agg(category ORDER BY category),'[]') FROM (SELECT DISTINCT category FROM public.project_boq_items WHERE category<>'') c),'scopes',(SELECT jsonb_agg(scope ORDER BY scope) FROM (SELECT DISTINCT scope FROM public.project_boq_items UNION SELECT unnest(ARRAY['Factory','On-Site Civil','Both'])) s),'audit',coalesce((SELECT jsonb_agg(to_jsonb(a) ORDER BY a.created_at DESC) FROM (SELECT * FROM public.boq_entry_audit WHERE boq_id=h.id ORDER BY created_at DESC LIMIT 100) a),'[]'));
END $$;
CREATE OR REPLACE FUNCTION public.boq1_mutate(p_project uuid,p_action text,p_payload jsonb,p_expected_version integer DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$ DECLARE h public.project_boq%ROWTYPE; bid uuid; rows jsonb; total numeric; n integer; reason text; warning jsonb; line uuid; key text; BEGIN
IF NOT public.boq1_can_write(p_project) THEN RAISE EXCEPTION 'Only an authorised BOQ writer with project access may save this BOQ' USING ERRCODE='42501'; END IF;
PERFORM 1 FROM public.projects WHERE id=p_project AND NOT is_archived FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Project is not active'; END IF;
IF jsonb_typeof(p_payload)<>'object' OR (p_payload-ARRAY['control_total','source_note','rows','reason','line_id','warning_key','note'])<>'{}'::jsonb THEN RAISE EXCEPTION 'Only BOQ entry fields may be supplied' USING ERRCODE='22023'; END IF;
SELECT * INTO h FROM public.project_boq WHERE project_id=p_project AND entry_mode='fresh' AND NOT is_archived FOR UPDATE;
IF p_action='create' THEN IF EXISTS(SELECT 1 FROM public.project_boq WHERE project_id=p_project) THEN RAISE EXCEPTION 'This project already has a BOQ. Existing BOQs remain readable and unchanged; fresh entry is for projects without a BOQ' USING ERRCODE='42501'; END IF;
IF nullif(btrim(p_payload->>'control_total'),'') IS NULL THEN RAISE EXCEPTION 'Type the signed-document control total first'; END IF;
bid:=gen_random_uuid(); PERFORM set_config('hstack.boq_entry',bid::text,true); PERFORM set_config('hstack.boq_action','header_created',true); PERFORM set_config('hstack.boq_reason','',true);
INSERT INTO public.project_boq(id,project_id,entry_mode,control_total,source_note) VALUES(bid,p_project,'fresh',public._boq1_number(p_payload->>'control_total','Control total',true),p_payload->>'source_note'); RETURN public.boq1_get(p_project); END IF;
IF h.id IS NULL THEN RAISE EXCEPTION 'Save the control total and source note before entering lines'; END IF;
IF p_expected_version IS NULL OR p_expected_version<>h.entry_version THEN RAISE EXCEPTION 'This BOQ changed in another window. Reload before saving' USING ERRCODE='40001'; END IF;
IF p_action='preview' THEN RETURN jsonb_build_object('rows',public._boq1_rows(h.id,coalesce(p_payload->'rows','[]'),false)); END IF;
IF h.status='final' AND p_action NOT IN ('revise','acknowledge') THEN RAISE EXCEPTION 'This BOQ is final and locked. Make a balanced revision with a reason' USING ERRCODE='42501'; END IF;
IF p_action='revise' AND h.status<>'final' THEN RAISE EXCEPTION 'Revisions apply only to a final BOQ'; END IF;
reason:=nullif(btrim(p_payload->>'reason'),''); IF p_action='revise' AND reason IS NULL THEN RAISE EXCEPTION 'A reason is required for every revision' USING ERRCODE='22023'; END IF;
PERFORM set_config('hstack.boq_entry',h.id::text,true); PERFORM set_config('hstack.boq_action',p_action,true); PERFORM set_config('hstack.boq_reason',coalesce(reason,''),true);
IF p_action='acknowledge' THEN line:=(p_payload->>'line_id')::uuid; key:=p_payload->>'warning_key'; SELECT w INTO warning FROM public.project_boq_items i CROSS JOIN LATERAL jsonb_array_elements(public._boq1_warnings(h.id,to_jsonb(i))) w WHERE i.id=line AND i.boq_id=h.id AND NOT i.is_archived AND w->>'key'=key; IF warning IS NULL THEN RAISE EXCEPTION 'This warning changed; reload before acknowledging'; END IF;
INSERT INTO public.boq_warning_acknowledgements(project_id,boq_id,line_id,warning_key,warning,note,created_by,updated_by) VALUES(p_project,h.id,line,key,warning,nullif(btrim(p_payload->>'note'),''),auth.uid(),auth.uid()) ON CONFLICT(boq_id,line_id,warning_key) DO NOTHING;
INSERT INTO public.boq_entry_audit(project_id,boq_id,line_id,action,reason,new_value,created_by,updated_by) VALUES(p_project,h.id,line,'warning_acknowledged',p_payload->>'note',warning,auth.uid(),auth.uid());
ELSIF p_action IN ('save','revise') THEN
rows:=public._boq1_rows(h.id,coalesce(p_payload->'rows','[]'),true);
IF p_action='revise' AND EXISTS(SELECT 1 FROM jsonb_array_elements(rows) r WHERE jsonb_array_length(r->'errors')>0) THEN RAISE EXCEPTION 'Revision has line errors: %',rows USING ERRCODE='22023'; END IF;
IF p_payload ? 'control_total' THEN UPDATE public.project_boq SET control_total=public._boq1_number(p_payload->>'control_total','Control total',true) WHERE id=h.id; END IF;
IF p_payload ? 'source_note' THEN UPDATE public.project_boq SET source_note=p_payload->>'source_note' WHERE id=h.id; END IF;
ELSIF p_action<>'finalise' THEN RAISE EXCEPTION 'Unknown BOQ action'; END IF;
SELECT coalesce(sum(total_amount),0),count(*) INTO total,n FROM public.project_boq_items WHERE boq_id=h.id AND NOT is_archived;
IF p_action IN ('finalise','revise') THEN SELECT * INTO h FROM public.project_boq WHERE id=h.id; IF n=0 OR h.control_total<>total THEN RAISE EXCEPTION 'BOQ must contain at least one line and match the control total exactly in paise. Difference: %',h.control_total-total USING ERRCODE='22023'; END IF;
IF EXISTS(SELECT 1 FROM public.project_boq_items WHERE boq_id=h.id AND NOT is_archived AND (sno<=0 OR btrim(item_description)='' OR nullif(btrim(unit),'') IS NULL OR boq_qty<0 OR boq_rate<0)) THEN RAISE EXCEPTION 'Resolve line errors before finalising'; END IF; END IF;
UPDATE public.project_boq SET total_boq_value=total,tender_total_value=total,factory_scope_value=(SELECT coalesce(sum(total_amount),0) FROM public.project_boq_items WHERE boq_id=h.id AND NOT is_archived AND scope IN ('Factory','Both')),civil_scope_value=(SELECT coalesce(sum(total_amount),0) FROM public.project_boq_items WHERE boq_id=h.id AND NOT is_archived AND scope IN ('On-Site Civil','Both')),entry_version=entry_version+1,status=CASE WHEN p_action='finalise' THEN 'final' ELSE status END,final_at=CASE WHEN p_action='finalise' THEN now() ELSE final_at END,final_by=CASE WHEN p_action='finalise' THEN auth.uid() ELSE final_by END WHERE id=h.id;
RETURN public.boq1_get(p_project)||jsonb_build_object('save_results',coalesce(rows,'[]')); END $$;
REVOKE ALL ON FUNCTION public._boq1_number(text,text,boolean),public._boq1_normal(text),public._boq1_warnings(uuid,jsonb),public._boq1_header_guard(),public._boq1_line_guard(),public._boq1_audit(),public._boq1_rows(uuid,jsonb,boolean) FROM PUBLIC,anon,authenticated;
REVOKE ALL ON FUNCTION public.boq1_can_read(uuid),public.boq1_can_write(uuid),public.boq1_get(uuid),public.boq1_mutate(uuid,text,jsonb,integer) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.boq1_can_read(uuid),public.boq1_can_write(uuid),public.boq1_get(uuid),public.boq1_mutate(uuid,text,jsonb,integer) TO authenticated,service_role;
DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.commit_project_setup_upload(uuid,jsonb,jsonb,jsonb)'::regprocedure) INTO definition; definition:=replace(definition,E'BEGIN\n',E'BEGIN\n  -- BOQ_LEGACY_UPLOAD_VISIBLE = false: keep all other workbook operations unchanged.\n  IF jsonb_typeof(coalesce(p_boq_rows, ''[]''::jsonb)) <> ''array'' OR jsonb_array_length(coalesce(p_boq_rows, ''[]''::jsonb)) > 0 THEN\n    RAISE EXCEPTION ''BOQ sheet uploading is off. Enter this project BOQ in the BOQ tab; Material Plan and Subcontract Rates remain available.'' USING ERRCODE=''42501'';\n  END IF;\n'); EXECUTE definition; END $$;
COMMENT ON FUNCTION public.boq1_mutate(uuid,text,jsonb,integer) IS 'Fresh project BOQ entry only; no project-copy/template path. Amounts and audit actors/times are server-filled. Existing legacy BOQs are not edited. Draft removal archives and neutralises quantity/rate for unchanged legacy readers.';